insert into public.learning_content
(content_id,faculty,subject,content_type,access_tier,display_order,content_data,is_published)
values
('dph-pharmacology-note-101','Pharmacy','Diploma in Pharmacy','note','free',301,'{"title":"Introduction to Pharmacology and Therapeutics","english":"Pharmacology is the study of drugs and their interactions with living systems. It includes pharmacokinetics (what the body does to a drug), pharmacodynamics (what a drug does to the body), pharmacotherapeutics (use of drugs to prevent or treat disease), toxicology and clinical pharmacology. A drug may produce a desired therapeutic effect as well as unwanted effects. Rational medicine use considers the correct indication, patient, medicine, dose, route, timing and duration.","nepali":"Pharmacology भनेको औषधि र जीवित शरीरबीच हुने अन्तरक्रियाको अध्ययन हो। यसमा pharmacokinetics (शरीरले औषधिमाथि गर्ने प्रक्रिया), pharmacodynamics (औषधिले शरीरमा गर्ने प्रभाव), pharmacotherapeutics (रोग रोकथाम वा उपचारमा औषधिको प्रयोग), toxicology र clinical pharmacology पर्छन्। औषधिले चाहिएको therapeutic effect सँगै unwanted effect पनि दिन सक्छ। औषधि तर्कसंगत रूपमा प्रयोग गर्दा सही indication, बिरामी, औषधि, dose, route, समय र अवधि विचार गर्नुपर्छ।"}'::jsonb,true),
('dph-pharmacology-note-102','Pharmacy','Diploma in Pharmacy','note','free',302,'{"title":"Pharmacokinetics: Absorption, Distribution, Metabolism and Excretion","english":"Pharmacokinetics is commonly summarized as ADME. Absorption is movement of a drug from its administration site into systemic circulation. Distribution is reversible movement between blood and tissues and is influenced by blood flow, tissue permeability and protein binding. Metabolism, often in the liver, converts drugs into metabolites; some are active and others inactive. Excretion removes drug or metabolites, mainly through the kidneys for many medicines. Bioavailability is the fraction of an administered dose reaching systemic circulation unchanged.","nepali":"Pharmacokinetics लाई ADME भनेर सम्झन सकिन्छ। Absorption भनेको औषधि दिएको स्थानबाट systemic circulation मा प्रवेश गर्ने प्रक्रिया हो। Distribution रगत र tissue बीच औषधि सर्ने प्रक्रिया हो; blood flow, tissue permeability र protein binding ले असर गर्छ। Metabolism प्रायः liver मा भई औषधिलाई metabolite मा बदल्छ; केही सक्रिय र केही निष्क्रिय हुन्छन्। Excretion ले औषधि वा metabolite शरीरबाट निकाल्छ, धेरै औषधिमा kidney मुख्य मार्ग हो। Bioavailability भनेको दिएको dose मध्ये unchanged अवस्थामा systemic circulation पुग्ने अंश हो।"}'::jsonb,true),
('dph-pharmacology-note-103','Pharmacy','Diploma in Pharmacy','note','free',303,'{"title":"Routes of Drug Administration","english":"Common routes include oral, sublingual, buccal, rectal, intravenous, intramuscular, subcutaneous, inhalational, topical and transdermal. Oral administration is convenient but absorption may be affected by food, gastrointestinal conditions and first-pass metabolism. Intravenous administration delivers a drug directly into the circulation and has complete bioavailability, but errors or adverse reactions can occur rapidly. The route is selected according to the medicine, clinical need, patient condition and product instructions.","nepali":"औषधि दिने सामान्य मार्गमा oral, sublingual, buccal, rectal, intravenous, intramuscular, subcutaneous, inhalational, topical र transdermal पर्छन्। Oral route सजिलो हुन्छ तर खाना, gastrointestinal अवस्था र first-pass metabolism ले absorption असर गर्न सक्छ। Intravenous route बाट औषधि सीधै circulation मा पुग्छ र bioavailability पूर्ण हुन्छ, तर गल्ती वा adverse reaction छिटो देखिन सक्छ। औषधि, clinical आवश्यकता, बिरामीको अवस्था र product instruction अनुसार route छानिन्छ।"}'::jsonb,true),
('dph-pharmacology-note-104','Pharmacy','Diploma in Pharmacy','note','free',304,'{"title":"Pharmacodynamics: Receptors and Drug Response","english":"Pharmacodynamics describes the biochemical and physiological effects of drugs and their mechanisms of action. Many drugs act by binding to receptors. An agonist binds to a receptor and activates it; an antagonist binds and blocks or reduces activation by an agonist. Drug response may depend on dose, receptor number, sensitivity and patient factors. Potency describes the amount of drug needed to produce an effect, whereas efficacy describes the maximum effect a drug can produce.","nepali":"Pharmacodynamics ले औषधिले शरीरमा पार्ने biochemical तथा physiological प्रभाव र काम गर्ने तरिका वर्णन गर्छ। धेरै औषधिले receptor सँग bind भएर काम गर्छन्। Agonist ले receptor मा bind भई सक्रिय बनाउँछ; antagonist ले bind गरेर agonist को activation रोक्छ वा घटाउँछ। औषधिको प्रतिक्रिया dose, receptor को संख्या तथा sensitivity र बिरामीका अवस्थाले असर गर्छ। Potency ले प्रभावका लागि चाहिने औषधिको मात्रा जनाउँछ भने efficacy ले औषधिले दिन सक्ने अधिकतम प्रभाव जनाउँछ।"}'::jsonb,true),
('dph-pharmacology-note-105','Pharmacy','Diploma in Pharmacy','note','free',305,'{"title":"Adverse Drug Reactions, Interactions and Safe Use","english":"An adverse drug reaction (ADR) is a harmful and unintended response to a medicine used at normally appropriate doses. Side effects, allergy, toxicity and interactions are important medication-safety concerns. Drug interactions may alter the effect of another drug and can be pharmacokinetic or pharmacodynamic. Check allergies, current medicines, dose, expiry and relevant patient factors; counsel patients not to share medicines or change prescribed treatment without professional advice. Suspected serious ADRs should be managed promptly and reported through the applicable pharmacovigilance system.","nepali":"Adverse drug reaction (ADR) भनेको सामान्य उपयुक्त dose मा प्रयोग गरिएको औषधिबाट हुने हानिकारक र अनिच्छित प्रतिक्रिया हो। Side effect, allergy, toxicity र drug interaction औषधि सुरक्षाका महत्त्वपूर्ण विषय हुन्। Drug interaction ले अर्को औषधिको प्रभाव बदल्न सक्छ र pharmacokinetic वा pharmacodynamic हुन सक्छ। Allergy, हाल प्रयोग भइरहेका औषधि, dose, expiry र बिरामीका सम्बन्धित अवस्था जाँच्नुहोस्; औषधि अरूलाई बाँड्न वा सल्लाहबिना prescribed उपचार परिवर्तन गर्न नदिनुहोस्। गम्भीर ADR शंका भए तुरुन्त व्यवस्थापन गरी लागू pharmacovigilance प्रणालीमा report गर्नुपर्छ।"}'::jsonb,true),
('dph-pharmacology-mcq-101','Pharmacy','Diploma in Pharmacy','mcq','free',301,'{"question":"Pharmacokinetics is best described as:","translation":"Pharmacokinetics भन्नाले के बुझिन्छ?","options":["What the drug does to the body","What the body does to the drug","Only adverse effects","Only drug classification"],"correctIndex":1,"explanation":"Pharmacokinetics describes absorption, distribution, metabolism and excretion of drugs.","explanationNe":"Pharmacokinetics ले औषधिको absorption, distribution, metabolism र excretion वर्णन गर्छ।"}'::jsonb,true),
('dph-pharmacology-mcq-102','Pharmacy','Diploma in Pharmacy','mcq','free',302,'{"question":"Which process is represented by the letter M in ADME?","translation":"ADME मा M ले कुन प्रक्रिया जनाउँछ?","options":["Movement","Metabolism","Medication","Measurement"],"correctIndex":1,"explanation":"M stands for metabolism, the chemical conversion of a drug in the body.","explanationNe":"M ले metabolism जनाउँछ, जसमा शरीरभित्र औषधिको रासायनिक परिवर्तन हुन्छ।"}'::jsonb,true),
('dph-pharmacology-mcq-103','Pharmacy','Diploma in Pharmacy','mcq','free',303,'{"question":"Which route provides 100% bioavailability by definition?","translation":"परिभाषाअनुसार कुन route मा bioavailability १००% हुन्छ?","options":["Oral","Intramuscular","Intravenous","Subcutaneous"],"correctIndex":2,"explanation":"An intravenous dose enters systemic circulation directly, so its bioavailability is 100%.","explanationNe":"Intravenous dose सीधै systemic circulation मा पुग्ने भएकाले यसको bioavailability १००% हुन्छ।"}'::jsonb,true),
('dph-pharmacology-mcq-104','Pharmacy','Diploma in Pharmacy','mcq','free',304,'{"question":"A drug that binds to a receptor and activates it is called:","translation":"Receptor मा bind भएर सक्रिय बनाउने औषधिलाई के भनिन्छ?","options":["Antagonist","Agonist","Inhibitor only","Placebo"],"correctIndex":1,"explanation":"An agonist binds to and activates a receptor to produce a response.","explanationNe":"Agonist ले receptor मा bind भएर सक्रिय बनाउँछ र प्रतिक्रिया उत्पन्न गर्छ।"}'::jsonb,true),
('dph-pharmacology-mcq-105','Pharmacy','Diploma in Pharmacy','mcq','free',305,'{"question":"Which organ is a major site of metabolism for many drugs?","translation":"धेरै औषधिको metabolism हुने प्रमुख अंग कुन हो?","options":["Liver","Spleen","Skin","Appendix"],"correctIndex":0,"explanation":"The liver contains many enzymes involved in drug metabolism, although other tissues can also metabolize drugs.","explanationNe":"Liver मा औषधिको metabolism गर्ने धेरै enzyme हुन्छन्, यद्यपि अन्य tissue ले पनि metabolism गर्न सक्छन्।"}'::jsonb,true),
('dph-pharmacology-mcq-106','Pharmacy','Diploma in Pharmacy','mcq','free',306,'{"question":"An antagonist generally:","translation":"Antagonist ले सामान्यतया के गर्छ?","options":["Activates a receptor","Blocks receptor activation","Always destroys the receptor","Increases bioavailability"],"correctIndex":1,"explanation":"An antagonist binds to a receptor and prevents or reduces activation by an agonist.","explanationNe":"Antagonist ले receptor मा bind भएर agonist द्वारा हुने activation रोक्छ वा घटाउँछ।"}'::jsonb,true),
('dph-pharmacology-mcq-107','Pharmacy','Diploma in Pharmacy','mcq','free',307,'{"question":"Bioavailability refers to the fraction of a dose that:","translation":"Bioavailability ले dose को कुन अंश जनाउँछ?","options":["Is excreted in urine","Reaches systemic circulation unchanged","Binds to plasma protein only","Is stored in fat"],"correctIndex":1,"explanation":"Bioavailability is the fraction of an administered dose reaching systemic circulation unchanged.","explanationNe":"दिएको dose मध्ये unchanged अवस्थामा systemic circulation पुग्ने अंश bioavailability हो।"}'::jsonb,true),
('dph-pharmacology-mcq-108','Pharmacy','Diploma in Pharmacy','mcq','free',308,'{"question":"A harmful, unintended response to a medicine at normally used doses is called:","translation":"सामान्य dose मा औषधि प्रयोग गर्दा हुने हानिकारक अनिच्छित प्रतिक्रियालाई के भनिन्छ?","options":["Therapeutic effect","Adverse drug reaction","Indication","Bioequivalence"],"correctIndex":1,"explanation":"This is the standard definition of an adverse drug reaction (ADR).","explanationNe":"यो adverse drug reaction (ADR) को मानक परिभाषा हो।"}'::jsonb,true),
('dph-pharmacology-mcq-109','Pharmacy','Diploma in Pharmacy','mcq','free',309,'{"question":"Which route is most directly affected by first-pass metabolism?","translation":"First-pass metabolism ले कुन route लाई बढी असर गर्छ?","options":["Intravenous","Oral","Inhalational","Topical"],"correctIndex":1,"explanation":"Absorbed oral drugs may pass through the intestinal wall and liver before reaching systemic circulation.","explanationNe":"Oral औषधि systemic circulation पुग्नुअघि intestinal wall र liver हुँदै जान सक्छ, त्यसैले first-pass metabolism को असर पर्छ।"}'::jsonb,true),
('dph-pharmacology-mcq-110','Pharmacy','Diploma in Pharmacy','mcq','free',310,'{"question":"Which is an important step before dispensing a medicine?","translation":"औषधि dispense गर्नुअघि कुन काम महत्त्वपूर्ण हुन्छ?","options":["Ignore allergy history","Check the prescription and patient allergies","Remove the expiry date","Recommend sharing medicines"],"correctIndex":1,"explanation":"Checking the prescription and allergy history helps prevent medication errors and avoidable harm.","explanationNe":"Prescription र allergy history जाँच्दा medication error र टार्न सकिने हानि रोक्न मद्दत हुन्छ।"}'::jsonb,true),
('dph-pharmacology-mock-101','Pharmacy','Diploma in Pharmacy','mock','free',401,'{"question":"Explain ADME and define bioavailability with one example.","answer":"ADME means absorption, distribution, metabolism and excretion. Bioavailability is the fraction of an administered dose reaching systemic circulation unchanged; an intravenous dose has 100% bioavailability.","answerNe":"ADME भनेको absorption, distribution, metabolism र excretion हो। Bioavailability भनेको दिएको dose मध्ये unchanged अवस्थामा systemic circulation पुग्ने अंश हो; intravenous dose को bioavailability १००% हुन्छ।"}'::jsonb,true),
('dph-pharmacology-mock-102','Pharmacy','Diploma in Pharmacy','mock','free',402,'{"question":"Differentiate an agonist from an antagonist.","answer":"An agonist binds to and activates a receptor; an antagonist binds to a receptor and blocks or reduces activation by an agonist.","answerNe":"Agonist ले receptor मा bind भएर सक्रिय बनाउँछ; antagonist ले receptor मा bind भएर agonist को activation रोक्छ वा घटाउँछ।"}'::jsonb,true),
('dph-pharmacology-mock-103','Pharmacy','Diploma in Pharmacy','mock','free',403,'{"question":"List four common routes of drug administration and one factor affecting route selection.","answer":"Examples include oral, intravenous, intramuscular and topical routes. Route selection depends on the medicine, urgency, patient condition and product instructions.","answerNe":"Oral, intravenous, intramuscular र topical सामान्य route हुन्। औषधि, उपचारको urgency, बिरामीको अवस्था र product instruction अनुसार route छानिन्छ।"}'::jsonb,true),
('dph-pharmacology-mock-104','Pharmacy','Diploma in Pharmacy','mock','free',404,'{"question":"What is an adverse drug reaction? Mention two safe-dispensing checks.","answer":"An ADR is a harmful and unintended response to a medicine used at normally appropriate doses. Check the prescription, patient identity, allergies, dose, expiry and current medicines as applicable.","answerNe":"सामान्य उपयुक्त dose मा औषधि प्रयोग गर्दा हुने हानिकारक अनिच्छित प्रतिक्रिया ADR हो। आवश्यकताअनुसार prescription, बिरामीको पहिचान, allergy, dose, expiry र हालका औषधि जाँच्नुपर्छ।"}'::jsonb,true),
('dph-pharmacology-mock-105','Pharmacy','Diploma in Pharmacy','mock','free',405,'{"question":"Differentiate potency and efficacy.","answer":"Potency is the amount of drug needed to produce a specified effect; efficacy is the maximum effect the drug can produce.","answerNe":"Potency भनेको निश्चित प्रभाव दिन चाहिने औषधिको मात्रा हो; efficacy भनेको औषधिले दिन सक्ने अधिकतम प्रभाव हो।"}'::jsonb,true)
